#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7
cd "$(dirname "$0")/.."
if [[ ! -t 0 ]]; then
  warn "Wizard potřebuje interaktivní terminál (ne ! v Claude Code). Spusť: cd $(pwd) && ./scripts/setup-objednavky.sh"
  exit 1
fi
for k in SANITY_PROJECT_ID SANITY_DATASET SANITY_WRITE_TOKEN STRIPE_SECRET_KEY SHOP_URL; do
  printf -v "$k" '%s' "$(_existing "$k" || true)"
  [[ -n "${!k}" ]] || { warn "$k chybí v .env, nejdřív spusť ./scripts/setup.sh"; exit 1; }
done

banner "Kalendáře e-shop: doručení, sklad, stavy objednávky a e-maily"

stage "Stripe CLI a lokální webhook secret"
say "Stripe CLI přeposílá platby z testovacího režimu na localhost (potřebuje to E2E test)."
if ! command -v stripe >/dev/null 2>&1; then
  if confirm "Nainstalovat Stripe CLI přes Homebrew?"; then
    brew install stripe/stripe-cli/stripe
  else
    SKIPPED+=("Stripe CLI: brew install stripe/stripe-cli/stripe, pak stripe listen --print-secret → STRIPE_WEBHOOK_SECRET")
  fi
fi
if command -v stripe >/dev/null 2>&1; then
  # --api-key, not stripe login: login may pick a different account/sandbox than the key in .env
  secret=$(stripe listen --api-key "$STRIPE_SECRET_KEY" --print-secret || true)
  if [[ "$secret" == whsec_* ]]; then
    write_env STRIPE_WEBHOOK_SECRET "$secret"
  else
    SKIPPED+=("STRIPE_WEBHOOK_SECRET: stripe listen --print-secret selhalo")
  fi
fi
pause

stage "Stripe: událost charge.refunded"
say "Storno funguje přes vrácení peněz, webhook proto musí dostávat i charge.refunded."
WEBHOOK_URL="$SHOP_URL/api/stripe-webhook"
endpoint=$(curl -sS -u "$STRIPE_SECRET_KEY:" "https://api.stripe.com/v1/webhook_endpoints?limit=100" \
  | node -e 'const d=JSON.parse(require("fs").readFileSync(0));const e=(d.data||[]).find(e=>e.url===process.argv[1]);process.stdout.write(e?e.id+" "+e.enabled_events.join(","):"")' "$WEBHOOK_URL" || true)
if [[ -z "$endpoint" ]]; then
  warn "Webhook pro $WEBHOOK_URL ve Stripe (test režim) nenalezen."
  SKIPPED+=("Stripe: Developers → Webhooks → $WEBHOOK_URL, přidat události charge.refunded a checkout.session.async_payment_succeeded")
elif [[ "$endpoint" == *charge.refunded* && "$endpoint" == *async_payment_succeeded* ]]; then
  note "charge.refunded i async_payment_succeeded už jsou zapnuté, přeskakuju."
elif confirm "Přidat charge.refunded a async_payment_succeeded na webhook $WEBHOOK_URL?"; then
  curl -sS -u "$STRIPE_SECRET_KEY:" "https://api.stripe.com/v1/webhook_endpoints/${endpoint%% *}" \
    -d "enabled_events[]=checkout.session.completed" -d "enabled_events[]=checkout.session.async_payment_succeeded" -d "enabled_events[]=charge.refunded" >/dev/null \
    && printf '  %s✓ set%s charge.refunded na webhooku\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Stripe: přidat charge.refunded na webhook $WEBHOOK_URL")
fi
pause

stage "Resend: e-maily"
say "Přes Resend chodí kupujícímu i obchodníkovi e-maily o objednávce."
open_url "https://resend.com/api-keys"
step "Přihlas se nebo založ účet a klikni na 'Create API key'."
step "Name: kalendar-eshop, Permission: Sending access, a pak 'Add'."
step "Klíč (začíná re_) se zobrazí jen jednou, zkopíruj ho."
ask_secret RESEND_API_KEY "Vlož API key:"
write_env RESEND_API_KEY "$RESEND_API_KEY"
note "Bez ověřené domény Resend doručuje jen na e-mail účtu, takže tam zadej ten."
ask MERCHANT_EMAIL "E-mail obchodníka (dostává Nová objednávka, je v patičce e-mailů):"
write_env MERCHANT_EMAIL "$MERCHANT_EMAIL"
pause

stage "Odběrní místo"
say "Text, který kupující uvidí u Osobního odběru (adresa, otvírací doba)."
ask PICKUP_PLACE "Odběrní místo:"
write_env PICKUP_PLACE "$PICKUP_PLACE"
note "Cena Doručení na adresu je 99 Kč; změníš ji v .env přes DELIVERY_PRICE_CZK."
pause

stage "Sanity: webhook Objednávka vyřízena"
say "Když ve Studiu přepneš objednávku na Vyřízená, Sanity zavolá e-shop a ten pošle e-mail."
SANITY_WEBHOOK_SECRET=$(_existing SANITY_WEBHOOK_SECRET || openssl rand -hex 32)
write_env SANITY_WEBHOOK_SECRET "$SANITY_WEBHOOK_SECRET"
open_url "https://www.sanity.io/manage/project/$SANITY_PROJECT_ID/api/webhooks"
step "Klikni na 'Create webhook' a vyplň:"
note "  Name:          Objednávka vyřízena"
note "  URL:           $SHOP_URL/api/sanity-webhook"
note "  Dataset:       $SANITY_DATASET"
note "  Trigger on:    jen Update"
note "  Filter:        _type == \"order\" && stav == \"vyrizena\" && delta::changedAny(stav)"
note "  Projection:    {_id, stav}"
note "  HTTP method:   POST, drafty vypnuté"
note "  Secret:        $SANITY_WEBHOOK_SECRET"
step "Ulož ('Apply webhook'). Na localhost Sanity nedosáhne, funguje to až na nasazeném e-shopu."
pause "Až bude webhook uložený, stiskni Enter."

stage "Cloudflare: tajné hodnoty"
say "Nasazený e-shop potřebuje stejné hodnoty jako .env."
note "STRIPE_WEBHOOK_SECRET se nenahrává, produkce má vlastní (nahrál ho setup.sh)."
if confirm "Nahrát RESEND_API_KEY, MERCHANT_EMAIL, PICKUP_PLACE a SANITY_WEBHOOK_SECRET do Workeru?"; then
  for k in RESEND_API_KEY MERCHANT_EMAIL PICKUP_PLACE SANITY_WEBHOOK_SECRET; do
    printf '%s' "${!k}" | pnpm exec wrangler secret put "$k"
  done
else
  SKIPPED+=("Cloudflare: wrangler secret put RESEND_API_KEY / MERCHANT_EMAIL / PICKUP_PLACE / SANITY_WEBHOOK_SECRET")
fi
pause

stage "Studio: Skladem (ks)"
say "Produkt bez vyplněného skladu se počítá jako 0 kusů, tedy Vyprodáno."
step "V druhém terminálu spusť: pnpm studio (nasazené Studio pole Skladem ještě nemá)."
open_url "http://localhost:3333"
step "U každého produktu vyplň 'Skladem (ks)' a klikni na 'Publish'."
query='count(*[_type == "product" && !defined(stock) && !(_id in path("drafts.**"))])'
while true; do
  pause "Až budou produkty publikované, stiskni Enter a já to zkontroluju."
  missing=$(curl -sS -G -H "Authorization: Bearer $SANITY_WRITE_TOKEN" \
    "https://$SANITY_PROJECT_ID.api.sanity.io/v2025-01-01/data/query/$SANITY_DATASET" \
    --data-urlencode "query=$query" | node -e 'process.stdout.write(String(JSON.parse(require("fs").readFileSync(0)).result))' || echo "?")
  [[ "$missing" == 0 ]] && { printf '  %s✓%s všechny produkty mají sklad\n' "$GREEN" "$RESET"; break; }
  warn "Produkty bez skladu: $missing"
  confirm "Zkusit znovu?" || { SKIPPED+=("Studio: vyplnit Skladem (ks) u $missing produktů"); break; }
done

finish
say "E2E test: npx playwright install chromium (jednou)"
say "          druhý terminál: set -a; . ./.env; set +a; stripe listen --api-key \"\$STRIPE_SECRET_KEY\" --events checkout.session.completed,checkout.session.async_payment_succeeded,charge.refunded --forward-to localhost:3000/api/stripe-webhook"
say "          pnpm test:e2e"
}

run_wizard "$@"; exit
